  'terms.acceptance.body': 'Chatyy का उपयोग करते समय, आप इन सेवा की शर्तों से सहमत होते हैं। यदि आप इन शर्तों के किसी भी भाग से सहमत नहीं हैं, तो सेवा का उपयोग न करें।',
  'terms.services.title': 'सेवाओं का विवरण',
