  'terms.accounts.title': 'उपयोगकर्ता खाते',
  'terms.accounts.body': 'आप अपनी क्रेडेंशियल्स की सुरक्षा बनाए रखने के लिए जिम्मेदार हैं। अपना पासवर्ड साझा न करें और अपनी खाता तक अनधिकृत पहुँच की अनुमति न दें। इस सेवा का उपयोग करने के लिए आपकी आयु कम से कम 13 वर्ष होनी चाहिए।',
  'terms.conduct.title': 'स्वीकृत उपयोग',
  'terms.conduct.body': 'आप सहमत होते हैं कि सेवा का उपयोग स्पैम, मैलवेयर, फ़िशिंग या किसी भी अवैध सामग्री भेजने के लिए नहीं किया जाएगा। अन्य उपयोगकर्ताओं के खातों तक पहुँचने या सेवा की अवसंरचना को बाधित करने का प्रयास न करें।',
  'terms.content.title': 'सामग्री की संपत्ति',
  'terms.content.body': 'आप सेवा के माध्यम से बनाई गई और भेजी गई सभी सामग्री के मालिक बने रहते हैं। हम आपके ईमेल या अटैचमेंट पर स्वामित्व का दावा नहीं करते हैं। हम सेवा प्रदान करने के लिए आवश्यकतानुसार सामग्री को संसाधित कर सकते हैं।',
  'terms.limitation.title': 'जिम्मेदारी की सीमा',
  'terms.limitation.body': 'Chatyy "जैसा है" प्रदान किया गया है। हम 99.9% उपलब्धता का प्रयास करते हैं लेकिन निरंतर सेवा की गारंटी नहीं देते। सेवा के उपयोग से होने वाले अप्रत्यक्ष, आकस्मिक या परिणामी नुकसान के लिए हम जिम्मेदार नहीं हैं।',
  'terms.termination.title': 'खाता समाप्ति',
  'terms.termination.body': 'हम उन खातों को निलंबित या समाप्त कर सकते हैं जो इन शर्तों का उल्लंघन करते हैं। आप कभी भी सेटिंग्स में अपना खाता हटा सकते हैं। समाप्ति के बाद, आपके डेटा 30 दिनों के भीतर हटा दिए जाएंगे।',
  'terms.changes.title': 'शर्तों में परिवर्तन',
  'terms.changes.body': 'हम समय-समय पर इन शर्तों को अपडेट कर सकते हैं। महत्वपूर्ण परिवर्तनों के बारे में हम ईमेल या ऐप में नोटिफिकेशन के माध्यम से सूचित करेंगे। परिवर्तनों के बाद निरंतर उपयोग अद्यतन शर्तों की स्वीकृति है।',

