  'plans.faqWhatIsPlusAnswer': 'यह Chatyy की प्रीमियम योजना है जो आपकी सभी बातचीत, तस्वीरें और वीडियो की सुरक्षा करती है। Chatyy One के साथ, यदि आप कुछ गलती से हटा देते हैं, तो आप इसे 30 दिनों के भीतर पुनर्प्राप्त कर सकते हैं। इसके अलावा, आपको 200GB स्टोरेज, One AI व्यक्तिगत सहायक के रूप में, और 100MB तक के फ़ाइलें भेजने की अनुमति मिलती है।',
